            if (y < 0) break;

            // Calculate bananas = (x+1)*(y+1)*(x+y)/2
            // We need to be careful about overflow, but the problem says answer <= 10^18.
            // Let's compute step by step.
            long term1 = x + 1;
            long term2 = y + 1;
            long term3 = x + y;

            // Compute (term1 * term2 * term3) / 2
            // To avoid overflow, we can divide one of the even terms by 2 first.
            long product;
            if (term1 % 2 == 0) {
                product = (term1 / 2) * term2 * term3;
            } else if (term2 % 2 == 0) {
                product = term1 * (term2 / 2) * term3;
            } else {
                product = term1 * term2 * (term3 / 2);
            }

            if (product > maxBananas) {
                maxBananas = product;
            }
        }

        System.out.println(maxBananas);
    }
